def controls(item,parts,payload):
 digest=hashlib.sha256(json.dumps(payload,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
 return '<fieldset><legend>Revisión independiente · '+html.escape(item)+'</legend>'+''.join('<label>'+html.escape(part)+' <select data-item="'+html.escape(item)+'" data-component="'+part+'" data-hash="'+digest+'"><option value="pending">Pendiente</option><option value="approve_proposal">Proponer aprobar</option><option value="changes">Pedir corrección</option><option value="reject">Rechazar propuesta</option></select></label> ' for part in parts)+'</fieldset>'
start='<h2>Propuestas de portada · elección independiente</h2><p>Originales reales autorizados por licencia; aprobación humana pendiente. No se generaron ilustraciones. Se muestran sin recorte para conservar el atractivo.</p><p>Las decisiones de esta pantalla son borradores locales; se exportan para revisión del coordinador y no publican ni autorizan generación automáticamente.</p><label>Persona revisora <input id="reviewer" placeholder="Nombre de quien revisa"></label><button id="export-review">Exportar decisiones de revisión</button><p id="review-feedback" role="status"></p><div class="opciones">'
for a in choices:
 start+='<article id="'+a['id']+'"><h3>Propuesta '+str(a['number'])+'</h3><img src="'+a['image_file']+'" alt="'+html.escape(a['reason'])+'"><p>'+html.escape(a['reason'])+'</p><p>'+html.escape(a['author'])+' · '+a['photograph_date']+' · '+a['license']+'</p><a href="'+a['source_url']+'">Fuente / licencia</a><p>Escritorio y móvil: sin recorte, imagen completa. Elección, referencia y licencia pendientes por separado.</p>'+controls(a['id'],['eleccion_portada','referencia_foto','licencia'],a)+'</article>'
start+='</div><h2>Inventario ampliado · '+str(len(places))+' sitios propuestos</h2><p>Sin límite de tarjetas. Ubicaciones descriptivas documentadas; coordenadas y entradas exactas pendientes donde se indica.</p>'
for item in inventory:
 start+='<article><h3>'+html.escape(item['name'])+'</h3><p>'+html.escape(item['category']+' · '+item['location']['municipality']+' · '+item['location'].get('description',''))+'</p><p>'+html.escape(item['inclusion']+' · '+item['reason'])+'</p><p>Fotografía: '+html.escape(item['photo_status'])+'; ubicación exacta: '+html.escape(item['location']['exact_entrance_status'])+'</p>'
 p=next((p for p in places if p['slug']==item['id']),None)
 if p:
  for lang,t in p['translations'].items():start+='<p lang="'+lang+'"><strong>'+lang+':</strong> '+html.escape(t['description'])+'</p>'
  for sid in p['source_ids']:start+='<a href="'+urls[sid]+'">Fuente '+sid+'</a> '
 if p:start+=controls(item['id'],['inclusion','ubicacion','texto_es','texto_en','texto_pt-BR','referencia_foto','licencia'],p)
 start+='</article>'
start+='<h2>Actividades: propuestas editoriales, operadores y candidatos ocultos</h2>'
for e in ex:
 start+='<article><h3>'+html.escape(e.get('name',e['id']))+'</h3><p>'+html.escape(e['kind'])+'</p><p>Operador: '+html.escape(e.get('operator') or 'No prometido')+'; fotografía: '+html.escape(e['photo_status'])+'</p><p>'+html.escape(e.get('reason',e.get('validity','Borrador informativo sin garantía de disponibilidad.')))+'</p>'
 if e.get('image_file'):
  a=next(x for x in assets if x['file']==e['image_file'])
  start+='<img src="'+e['image_file']+'" alt="'+html.escape(e['image_scope'])+'"><p>'+html.escape(e['image_scope'])+'</p><p>'+html.escape(a['author'])+' · <a href="'+a['source_url']+'">Fuente</a> · <a href="'+a['license_url']+'">'+a['license']+'</a>. Miniatura técnica; sin aprobación.</p>'
 start+=controls(e['id'],(['texto_es','texto_en','texto_pt-BR'] if e.get('translations') else ['texto_es'])+['ubicacion','operador','referencia_foto'],e)
 if not e.get('translations'):start+='<p>EN/PT-BR de esta actividad ampliada pendientes; no disponibles para aprobar.</p>'
 start+='</article>'
start+='''<script>
const key='medellin-review-v2';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
document.querySelectorAll('select[data-item]').forEach(s=>{const id=s.dataset.item+':'+s.dataset.component;if(saved[id]?.hash===s.dataset.hash)s.value=saved[id].decision;s.addEventListener('change',()=>{saved[id]={item:s.dataset.item,component:s.dataset.component,hash:s.dataset.hash,decision:s.value};try{localStorage.setItem(key,JSON.stringify(saved))}catch{};document.querySelector('#review-feedback').textContent='Decisión local guardada; aún no comunicada ni aprobada por el coordinador.'})});
document.querySelector('#export-review').onclick=()=>{const reviewer=document.querySelector('#reviewer').value.trim();if(!reviewer){document.querySelector('#review-feedback').textContent='Indica quién revisa para exportar decisiones trazables.';return}const payload={destination:'CO-05-medellin',reviewer,at:new Date().toISOString(),status:'local_review_draft',decisions:Object.values(saved),generation_authorized:false,publication_authorized:false};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='medellin-revision-borrador.json';a.click();URL.revokeObjectURL(a.href);document.querySelector('#review-feedback').textContent='Decisiones exportadas. Compartir el archivo con el coordinador; no se genera ni publica contenido.'};
</script>'''
